//! Phantom Protocol — Post-quantum identity for Nexus users.
//!
//! Privacy Part 3: private keys are generated by the client and never sent to
//! the server. The server stores only the public keys (kem_public, signing_public)
//! and a DID derived from the username. The client registers via
//! POST /api/users/@me/phantom with a ClientPhantomRegistration body.

use base64::Engine;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// A Phantom post-quantum identity attached to a user (public keys only).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PhantomIdentity {
    pub user_id: Uuid,
    pub did: String,
    pub kem_public: String,     // base64 ML-KEM-1024 public key
    pub signing_public: String, // base64 ML-DSA-87 public key
    pub created_at: chrono::DateTime<chrono::Utc>,
}

/// Client-supplied registration payload for POST /api/users/@me/phantom.
///
/// Keys are generated on the client; only public halves are accepted here.
#[derive(Debug, Deserialize)]
pub struct ClientPhantomRegistration {
    pub kem_public: String,     // base64 ML-KEM-1024 public key
    pub signing_public: String, // base64 ML-DSA-87 public key
}

/// Verify a Dilithium-5 / ML-DSA-87 signature over a message.
pub fn verify_signature(public_b64: &str, message: &[u8], signature: &[u8]) -> bool {
    use pqcrypto_dilithium::dilithium5;
    use pqcrypto_traits::sign::{PublicKey as _, DetachedSignature};

    let pk_bytes = b64_decode(public_b64);
    let (Ok(pk), Ok(sig)) = (
        dilithium5::PublicKey::from_bytes(&pk_bytes),
        DetachedSignature::from_bytes(signature),
    ) else { return false };
    dilithium5::verify_detached_signature(&sig, message, &pk).is_ok()
}

fn b64_decode(s: &str) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD.decode(s).unwrap_or_default()
}

// Database access for Phantom identities deliberately does NOT live here.
// nexus-common is the foundation layer and sits below nexus-db.
// Storage: nexus_db::repository::phantom — get_identity, insert_identity, delete_identity.

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn client_registration_deserializes() {
        let json = r#"{"kem_public":"YWJj","signing_public":"ZGVm"}"#;
        let reg: ClientPhantomRegistration = serde_json::from_str(json).unwrap();
        assert_eq!(reg.kem_public, "YWJj");
        assert_eq!(reg.signing_public, "ZGVm");
    }

    #[test]
    fn verify_signature_rejects_bad_key() {
        // Garbage bytes: should return false, not panic.
        assert!(!verify_signature("bm90YWtleQ==", b"hello", b"notsig"));
    }
}
